// Package ratelimit implements a concurrency-safe token-bucket rate limiter.
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a token-bucket rate limiter. It is safe for concurrent use.
type Limiter struct {
	mu       sync.Mutex
	rate     float64   // tokens per second
	burst    float64   // bucket capacity
	tokens   float64   // current tokens
	last     time.Time // last refill time
	clock    Clock
}

// New creates a Limiter that refills rate tokens per second, with a maximum
// burst capacity. rate and burst must be > 0.
func New(rate float64, burst int) (*Limiter, error) {
	return NewWithClock(rate, burst, realClock{})
}

// NewWithClock is New with an injectable Clock.
func NewWithClock(rate float64, burst int, c Clock) (*Limiter, error) {
	if c == nil {
		return nil, errors.New("ratelimit: nil clock")
	}
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be > 0")
	}
	if burst <= 0 {
		return nil, errors.New("ratelimit: burst must be > 0")
	}
	return &Limiter{
		rate:  rate,
		burst: float64(burst),
		tokens: float64(burst),
		clock: c,
	}, nil
}

// advance refills tokens based on elapsed time. Caller must hold mu.
func (l *Limiter) advance(now time.Time) {
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
		l.last = now
	}
}

// AllowN reports whether n tokens may be consumed at time now.
// If allowed, the tokens are deducted.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(now)
	need := float64(n)
	if l.tokens >= need {
		l.tokens -= need
		return true
	}
	return false
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool { return l.AllowN(l.clock.Now(), 1) }

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
