// NewLimiter creates a Limiter that refills rate tokens per second,
// with a maximum capacity of burst tokens.
func NewLimiter(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if burst <= 0 {
		return nil, ErrNonPositiveBurst
	}
	if clock == nil {
		clock = realClock{}
	}
	return &Limiter{
		rate:   rate,
		burst:  float64(burst),
		tokens: float64(burst),
		clock:  clock,
	}, nil
}

// AllowN reports whether n tokens may be consumed at time now.
// It consumes the tokens if allowed.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	// Refill based on elapsed time since last refill.
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
		l.last = now
	}

	if float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Allow reports whether a single token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

