// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// realClock uses the system clock.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// Tokens refill continuously at rate tokens per second, up to burst capacity.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	burst    float64
	rate     float64 // tokens per second
	last     time.Time
	clock    Clock
}

var (
	ErrNonPositiveRate  = errors.New("ratelimit: rate must be > 0")
	ErrNonPositiveBurst = errors.New("ratelimit: burst must be > 0")
	ErrNilClock         = errors.New("ratelimit: clock must not be nil")
)

// New creates a Limiter with the given refill rate (tokens/sec) and burst
// capacity, starting full. clock may be nil for the real clock.
func New(rate, burst float64, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if burst <= 0 {
		return nil, ErrNonPositiveBurst
	}
	if clock == nil {
		clock = realClock{}
	}
	return &Limiter{
		tokens: burst,
		burst:  burst,
		rate:   rate,
		last:   clock.Now(),
		clock:  clock,
	}, nil
}

// advance refills tokens based on elapsed time. Caller must hold mu.
func (l *Limiter) advance(now time.Time) {
	if now.After(l.last) {
		elapsed := now.Sub(l.last).Seconds()
		l.tokens += elapsed * l.rate
		if l.tokens > l.burst {
			l.tokens = l.burst
		}
		l.last = now
	}
}

// AllowN reports whether n tokens may be consumed at time now.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(now)
	need := float64(n)
	if l.tokens >= need {
		l.tokens -= need
		return true
	}
	return false
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

// RetryAfter returns how long to wait until n tokens are available,
// capped at zero if immediately allowed.
func (l *Limiter) RetryAfter(n int) time.Duration {
	if n < 0 {
		return -1
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.clock.Now()
	l.advance(now)
	need := float64(n) - l.tokens
	if need <= 0 {
		return 0
	}
	return time.Duration(need / l.rate * float64(time.Second))
}
